const About = ({ imageData }) => {
  return (
    <section id="about" className="mx-auto max-w-7xl px-4 py-24 sm:px-6 lg:px-8">
      <div className="mb-10 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-sm uppercase tracking-[0.35em] text-amber-300">What to expect</p>
          <h2 className="text-3xl font-semibold text-white sm:text-4xl">Designed for comfort, connection, and calm.</h2>
        </div>
        <p className="max-w-2xl text-base text-slate-300">
          Every detail is shaped around a slower pace, thoughtful hospitality, and memorable experiences that feel effortless.
        </p>
      </div>

      <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
        {imageData.map((data) => (
          <article key={data.id} className="group overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900/60 shadow-glow">
            <div className="relative h-72 overflow-hidden">
              <img src={data.img} alt={data.title} className="h-full w-full object-cover transition duration-500 group-hover:scale-105" />
              <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent" />
              <div className="absolute bottom-0 left-0 p-6">
                <h3 className="text-xl font-semibold tracking-wide text-white">{data.title}</h3>
              </div>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
};

export default About;
